// SPDX-License-Identifier: MIT
//
// Dual clock FIFO, gray coded pointers, two flop synchronisers.
//
// The MII receive clock is generated by the PHY and has nothing to do with the
// Wishbone clock, so everything crossing between them goes through here.
// DEPTH must be a power of two.

module async_fifo #(
    parameter int WIDTH = 12,
    parameter int DEPTH = 64
) (
    // ---- write side ---------------------------------------------------------
    input  logic             wclk,
    input  logic             wrst,
    input  logic             wr_en,
    input  logic [WIDTH-1:0] wr_data,
    output logic             wfull,

    // ---- read side ----------------------------------------------------------
    input  logic             rclk,
    input  logic             rrst,
    input  logic             rd_en,
    output logic [WIDTH-1:0] rd_data,
    output logic             rempty
);

  localparam int AW = $clog2(DEPTH);

  initial begin
    if (DEPTH < 4 || (DEPTH & (DEPTH - 1)) != 0)
      $fatal(1, "async_fifo: DEPTH must be a power of two >= 4");
  end

  function automatic logic [AW:0] bin2gray(input logic [AW:0] b);
    bin2gray = b ^ (b >> 1);
  endfunction

  logic [WIDTH-1:0] mem [DEPTH];

  logic [AW:0] wbin, wgray, rbin, rgray;
  logic [AW:0] rgray_w1, rgray_w2;   // read pointer seen by the write side
  logic [AW:0] wgray_r1, wgray_r2;   // write pointer seen by the read side

  // ---- write side ---------------------------------------------------------
  wire        do_wr = wr_en && !wfull;
  wire [AW:0] wbin_next = wbin + {{AW{1'b0}}, do_wr};

  always_ff @(posedge wclk) begin
    if (wrst) begin
      wbin  <= '0;
      wgray <= '0;
    end else begin
      wbin  <= wbin_next;
      wgray <= bin2gray(wbin_next);
    end
  end

  always_ff @(posedge wclk) begin
    if (do_wr) mem[wbin[AW-1:0]] <= wr_data;
  end

  always_ff @(posedge wclk) begin
    if (wrst) begin
      rgray_w1 <= '0;
      rgray_w2 <= '0;
    end else begin
      rgray_w1 <= rgray;
      rgray_w2 <= rgray_w1;
    end
  end

  // Full when the pointers match except for the two most significant bits.
  assign wfull = (wgray == {~rgray_w2[AW:AW-1], rgray_w2[AW-2:0]});

  // ---- read side ----------------------------------------------------------
  wire        do_rd = rd_en && !rempty;
  wire [AW:0] rbin_next = rbin + {{AW{1'b0}}, do_rd};

  always_ff @(posedge rclk) begin
    if (rrst) begin
      rbin  <= '0;
      rgray <= '0;
    end else begin
      rbin  <= rbin_next;
      rgray <= bin2gray(rbin_next);
    end
  end

  always_ff @(posedge rclk) begin
    if (rrst) begin
      wgray_r1 <= '0;
      wgray_r2 <= '0;
    end else begin
      wgray_r1 <= wgray;
      wgray_r2 <= wgray_r1;
    end
  end

  assign rempty  = (rgray == wgray_r2);
  assign rd_data = mem[rbin[AW-1:0]];

endmodule
